update DAILY_TICKET_INSTANCE
set TICKET_STATUS = #{ticketStatus,jdbcType=VARCHAR},
    COUNTING_END = #{countingEnd,jdbcType=BIGINT},
    FIRST_USE_TIME = #{firstUseTime,jdbcType=TIMESTAMP},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where ID = #{id,jdbcType=VARCHAR}

update DAILY_TICKET_INSTANCE
set ACTUAL_TIMES = ACTUAL_TIMES - 1,
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where ID = #{id,jdbcType=VARCHAR}
  and ACTUAL_TIMES > 0

mapper.select:
select from DAILY_TICKET_INSTANCE where TICKET_STATUS in ('ACTIVATED', 'USED') and ( (COUNTING_END is not null and COUNTING_END < #{nowMillis,jdbcType=BIGINT})
or (COUNTING_END is null and ACTIVATE_TIME is not null and PERIOD is not null and PERIOD > 0 and ACTIVATE_TIME + NUMTODSINTERVAL(PERIOD, 'DAY') < #{now,jdbcType=TIMESTAMP})
) order by UPDATE_TIME fetch first #{limit,jdbcType=INTEGER} rows only

mapper.update:
update DAILY_TICKET_INSTANCE
set TICKET_STATUS = #{nextStatus,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where ID = #{id,jdbcType=VARCHAR}
  and TICKET_STATUS = #{expectStatus,jdbcType=VARCHAR}
